INSERT INTO ai_chat_messages (id, conversation_id, role, content, metadata, created_at) VALUES
('19100000-0000-0000-0000-000000000001', '19000000-0000-0000-0000-000000000001', 'user', '[{"type":"text","text":"Алексей — разработчик с высокой стабильной зарплатой, который много лет не вёл бюджет, но уже накопил сильную базу: резерв, брокерский счёт и почти отсутствующие долги. Его главная проблема не выживание, а качество решений: сколько держать наличными, когда пополнять ИИС, как заметить инфляцию образа жизни, как не путать регулярные расходы с разовыми покупками техники и отпусков. В истории есть ровные зарплаты, дивиденды, ежемесячные продукты, транспорт, подписки, переводы в резерв и цель довести подушку до 12 месяцев расходов."}]'::jsonb, '{"scenario":"stable_salary_optimizer","password":"TestPassword123!"}'::jsonb, now()),
('19100000-0000-0000-0000-000000000002', '19000000-0000-0000-0000-000000000002', 'user', '[{"type":"text","text":"Ирина — фриланс-дизайнер с хорошим годовым доходом, но кассовые разрывы делают её финансовое состояние нервным. В одни месяцы приходят два крупных проекта, в другие почти ничего; часть денег лежит на электронном кошельке, часть уходит на софт, технику, налоги и обучение. У неё есть налоговая задолженность после удачного квартала, небольшая доля в студии и цель построить резерв, который позволит спокойно переживать задержки клиентов. Этот сценарий нужен для тестов нерегулярного дохода, прогнозирования, налоговых расходов и рекомендаций по сглаживанию денежного потока."}]'::jsonb, '{"scenario":"volatile_freelance_cash_flow","password":"TestPassword123!"}'::jsonb, now()),
('19100000-0000-0000-0000-000000000003', '19000000-0000-0000-0000-000000000003', 'user', '[{"type":"text","text":"Павел восстанавливается после периода просрочек: у него новая стабильная работа, автокредит, дорогая кредитная карта и маленький резерв, который нельзя обнулить одним платежом. История специально содержит высокую долговую нагрузку, платежи по двум обязательствам, отрицательный баланс кредитного счёта, регулярные продукты и осторожное накопление. В рекомендациях важно проверять приоритет дорогого долга, предупреждения о просрочках, баланс между досрочным погашением и минимальной подушкой, а также динамику чистого капитала, которая сначала выглядит отрицательной."}]'::jsonb, '{"scenario":"debt_repair_credit_rebuilding","password":"TestPassword123!"}'::jsonb, now()),
('19100000-0000-0000-0000-000000000004', '19000000-0000-0000-0000-000000000004', 'user', '[{"type":"text","text":"Елена ведёт семейный бюджет: ипотека, двое детей, школа, кружки, ремонт, коммунальные платежи и большая квартира как главный актив. Доход семьи высокий, но обязательные расходы тоже велики, поэтому любые рекомендации должны учитывать сезонность детских расходов, безопасность резерва, риск ремонта за счёт кредитки и долгую ипотечную траекторию. Сценарий хорошо проверяет долговую нагрузку с обеспеченным активом, цели на ремонт, переводы между счетами и регулярные платежи, которые нельзя просто сократить без контекста."}]'::jsonb, '{"scenario":"family_mortgage_pressure","password":"TestPassword123!"}'::jsonb, now()),
('19100000-0000-0000-0000-000000000005', '19000000-0000-0000-0000-000000000005', 'user', '[{"type":"text","text":"Николай на пенсии: у него есть пенсия, арендный доход, дивидендный портфель, квартира под сдачу и консервативные накопления. Главный риск не нехватка дохода сегодня, а сохранение капитала, медицинские расходы, ремонт арендуемой квартиры и помощь семье. История включает стабильные и инвестиционные доходы, растущие медицинские расходы, небольшой семейный долг без процентов и цель покрывать крупные расходы доходом, не продавая активы в плохой момент. Это сценарий для проверки рекомендаций пожилому пользователю с активами и чувствительностью к риску."}]'::jsonb, '{"scenario":"retirement_income_preservation","password":"TestPassword123!"}'::jsonb, now());
