\echo Загружаем 5 больших финансовых сценариев FinDoctor...

BEGIN;












SELECT gen_random_uuid(), v.user_id::uuid, v.account_id::uuid, v.category_id::uuid, v.type::transaction_type, v.amount::numeric, 'RUB',
       (date '2020-06-01' + (m.month_idx * interval '1 month') + (v.day_offset * interval '1 day'))::timestamp,
       v.description || ' | год истории ' || (m.month_idx / 12 + 1)::text
       || ' | сезон: ' || CASE
           WHEN m.month_idx % 12 IN (0, 1) THEN 'зимние расходы и страховые платежи'
           WHEN m.month_idx % 12 IN (2, 3, 4) THEN 'весеннее планирование и налоги'
           WHEN m.month_idx % 12 IN (5, 6, 7) THEN 'летние поездки, ремонт и нерегулярные покупки'
           WHEN m.month_idx % 12 IN (8, 9) THEN 'осенние платежи за обучение и быт'
           ELSE 'конец года, премии и закрытие долгов'
       END
       || ' | порядковый месяц ' || (m.month_idx + 1)::text,
       v.merchant_id::uuid, v.merchant_name, v.geo_location, v.recurring_id::uuid,
       v.external_prefix || '-' || m.month_idx::text, now()
FROM generate_series(0, 71) AS m(month_idx)
CROSS JOIN LATERAL (
    VALUES
    ('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000101','income',235000 + (m.month_idx / 12) * 18000 + CASE WHEN m.month_idx % 12 = 11 THEN 120000 ELSE 0 END,4,'Зарплата: стабильный высокий доход, ежегодная индексация и декабрьская премия',NULL,NULL,'Москва','14000000-0000-0000-0000-000000000001','scenario-u1-salary'),
    ('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000201','expense',47000 + (m.month_idx % 12) * 900,7,'Семейные продукты, повторяемая корзина без сильных выбросов','20000000-0000-0000-0000-000000000201','Тестовая сеть супермаркетов','Москва',NULL,'scenario-u1-grocery'),
    ('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000203','expense',18000 + CASE WHEN m.month_idx % 12 IN (5,6,7) THEN 7000 ELSE 0 END,12,'Транспорт, такси и сезонные поездки на работу','20000000-0000-0000-0000-000000000202','Тестовый городской транспорт','Москва',NULL,'scenario-u1-transport'),
    ('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000103','income',9000 + (m.month_idx / 12) * 2500,18,'Дивиденды и купоны по портфелю, маленький стабильный поток',NULL,NULL,'Москва',NULL,'scenario-u1-dividends'),
    ('10000000-0000-0000-0000-000000000002','11000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000102','income',90000 + (m.month_idx % 4) * 45000,6,'Оплата проекта: доход скачет, задержки клиентов создают кассовые разрывы',NULL,NULL,'Удалённо','14000000-0000-0000-0000-000000000002','scenario-u2-client-a'),
    ('10000000-0000-0000-0000-000000000002','11000000-0000-0000-0000-000000000005','00000000-0000-0000-0000-000000000102','income',35000 + (m.month_idx % 3) * 30000,19,'Малые проекты на кошелёк, много небольших поступлений',NULL,NULL,'Удалённо',NULL,'scenario-u2-client-b'),
    ('10000000-0000-0000-0000-000000000002','11000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000210','expense',26000 + (m.month_idx % 2) * 18000 + CASE WHEN m.month_idx % 12 = 8 THEN 55000 ELSE 0 END,9,'Покупка техники и софта для работы, часть расходов инвестиционная','20000000-0000-0000-0000-000000000204','Тестовый маркетплейс','Удалённо',NULL,'scenario-u2-equipment'),
    ('10000000-0000-0000-0000-000000000002','11000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000214','expense',22000 + CASE WHEN m.month_idx % 3 = 0 THEN 28000 ELSE 0 END,21,'Плановые налоговые платежи и взносы самозанятого',NULL,'ФНС','Москва',NULL,'scenario-u2-tax'),
    ('10000000-0000-0000-0000-000000000003','11000000-0000-0000-0000-000000000007','00000000-0000-0000-0000-000000000101','income',142000 + (m.month_idx / 12) * 12000,5,'Зарплата после смены работы, восстановление платёжной дисциплины',NULL,NULL,'Казань',NULL,'scenario-u3-salary'),
    ('10000000-0000-0000-0000-000000000003','11000000-0000-0000-0000-000000000007','00000000-0000-0000-0000-000000000215','expense',26000 + CASE WHEN m.month_idx % 6 = 5 THEN 14000 ELSE 0 END,8,'Платёж по кредитной карте, важен для сценариев долговой нагрузки',NULL,'Тестовый Региональный Кредит','Казань','14000000-0000-0000-0000-000000000003','scenario-u3-card-payment'),
    ('10000000-0000-0000-0000-000000000003','11000000-0000-0000-0000-000000000007','00000000-0000-0000-0000-000000000215','expense',31000 + CASE WHEN m.month_idx % 10 = 4 THEN 20000 ELSE 0 END,14,'Автокредит: регулярный платёж плюс иногда досрочное погашение',NULL,'Тестовый Региональный Кредит','Казань',NULL,'scenario-u3-car-payment'),
    ('10000000-0000-0000-0000-000000000003','11000000-0000-0000-0000-000000000007','00000000-0000-0000-0000-000000000201','expense',39000 + (m.month_idx % 12) * 700,20,'Продукты и бытовые покупки, бюджет жёстко ограничен','20000000-0000-0000-0000-000000000201','Тестовая сеть супермаркетов','Казань',NULL,'scenario-u3-grocery'),
    ('10000000-0000-0000-0000-000000000004','11000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000101','income',285000 + (m.month_idx / 12) * 25000 + CASE WHEN m.month_idx % 3 = 2 THEN 45000 ELSE 0 END,5,'Совокупный семейный доход: зарплата плюс ежеквартальные премии',NULL,NULL,'Москва',NULL,'scenario-u4-income'),
    ('10000000-0000-0000-0000-000000000004','11000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000215','expense',76000,5,'Ипотечный платёж, главный фиксированный расход семьи',NULL,'Тестовый Семейный Ипотечный Банк','Москва','14000000-0000-0000-0000-000000000004','scenario-u4-mortgage'),
    ('10000000-0000-0000-0000-000000000004','11000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000212','expense',44000 + (m.month_idx % 3) * 12000,11,'Дети: школа, кружки, сезонные сборы и медицина',NULL,NULL,'Москва',NULL,'scenario-u4-kids'),
    ('10000000-0000-0000-0000-000000000004','11000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000204','expense',33000,16,'ЖКХ, обслуживание квартиры и мелкий ремонт',NULL,NULL,'Москва',NULL,'scenario-u4-housing'),
    ('10000000-0000-0000-0000-000000000005','11000000-0000-0000-0000-000000000013','00000000-0000-0000-0000-000000000106','income',52000,3,'Пенсия, маленький стабильный доход',NULL,NULL,'Сочи',NULL,'scenario-u5-pension'),
    ('10000000-0000-0000-0000-000000000005','11000000-0000-0000-0000-000000000013','00000000-0000-0000-0000-000000000105','income',64000,10,'Арендный доход от квартиры, иногда задерживается',NULL,NULL,'Сочи','14000000-0000-0000-0000-000000000005','scenario-u5-rent'),
    ('10000000-0000-0000-0000-000000000005','11000000-0000-0000-0000-000000000013','00000000-0000-0000-0000-000000000205','expense',28000 + (m.month_idx % 4) * 9000 + CASE WHEN m.month_idx % 12 = 1 THEN 60000 ELSE 0 END,15,'Медицина и лекарства, главный риск бюджета','20000000-0000-0000-0000-000000000203','Тестовый медицинский центр','Сочи',NULL,'scenario-u5-health'),
    ('10000000-0000-0000-0000-000000000005','11000000-0000-0000-0000-000000000015','00000000-0000-0000-0000-000000000103','income',18000 + (m.month_idx % 2) * 7000 + (m.month_idx / 12) * 1500,22,'Дивиденды по консервативному портфелю',NULL,NULL,'Сочи',NULL,'scenario-u5-dividends')
) AS v(user_id, account_id, category_id, type, amount, day_offset, description, merchant_id, merchant_name, geo_location, recurring_id, external_prefix);

SELECT gen_random_uuid(), t.user_id, '13000000-0000-0000-0000-000000000002', t.id, '14000000-0000-0000-0000-000000000003',
       t.transaction_datetime::date, t.amount, t.amount * 0.64, t.amount * 0.36, 0, 'RUB',
       GREATEST(0, 240000 - (row_number() OVER (ORDER BY t.transaction_datetime) * 4200)), now()
FROM transactions t
WHERE t.external_id LIKE 'scenario-u3-card-payment-%';

SELECT gen_random_uuid(), t.user_id, '13000000-0000-0000-0000-000000000004', t.id, '14000000-0000-0000-0000-000000000004',
       t.transaction_datetime::date, t.amount, t.amount * 0.42, t.amount * 0.58, 0, 'RUB',
       GREATEST(0, 7800000 - (row_number() OVER (ORDER BY t.transaction_datetime) * 32000)), now()
FROM transactions t
WHERE t.external_id LIKE 'scenario-u4-mortgage-%';

SELECT id, '16000000-0000-0000-0000-000000000002'
FROM transactions
WHERE user_id = '10000000-0000-0000-0000-000000000002'
  AND external_id LIKE 'scenario-u2-%';

SELECT gen_random_uuid(), s.user_id::uuid, (date '2020-06-30' + (m.month_idx * interval '1 month'))::date,
       s.cash + m.month_idx * s.cash_delta,
       s.assets + m.month_idx * s.asset_delta,
       s.liabilities - m.month_idx * s.liability_delta,
       (s.cash + m.month_idx * s.cash_delta) + (s.assets + m.month_idx * s.asset_delta) - (s.liabilities - m.month_idx * s.liability_delta),
       s.monthly_income,
       s.monthly_expenses,
       s.savings_rate
FROM generate_series(0, 71) AS m(month_idx)
CROSS JOIN (
    VALUES
    ('10000000-0000-0000-0000-000000000001', 680000, 930000, 0, 43000, 22000, 0, 244000, 118000, 0.52),
    ('10000000-0000-0000-0000-000000000002', 180000, 850000, 146000, 12000, 16000, 5000, 210000, 168000, 0.20),
    ('10000000-0000-0000-0000-000000000003', 52000, 760000, 1092000, 9000, -12000, 41000, 142000, 111000, 0.12),
    ('10000000-0000-0000-0000-000000000004', 340000, 15800000, 7800000, 25000, 50000, 32000, 285000, 198000, 0.31),
    ('10000000-0000-0000-0000-000000000005', 1350000, 12500000, 300000, 18000, 42000, 15000, 134000, 91000, 0.32)
) AS s(user_id, cash, assets, liabilities, cash_delta, asset_delta, liability_delta, monthly_income, monthly_expenses, savings_rate);



COMMIT;

\echo Тестовые сценарии загружены. Пароль для всех пользователей: TestPassword123!
